// ============================================================
// Rule: LNX_Ngrok Free Usage
// Vendor: Linux
// Objective:
// Detect activity associated with LNX_Ngrok Free Usage.
// Severity: SEV_050_CRITICAL
// Category: EXFILTRATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0011 - Command and Control
// Technique: T1572 - Protocol Tunneling

// Habilita diferenciação entre maiúsculas e minúsculas nas comparações
config case_sensitive = true  

// Usa o preset "network_story", que consolida dados de tráfego de rede
| preset = network_story  

// Filtra processos cuja linha de comando contenha a string "ngrok-free.app"
// Indicador de uso de túnel reverso baseado em ngrok
| filter (`actor_process_command_line` contains """ngrok-free.app""")
